'use strict';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=v=>String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[đĐ]/g,'d').toLowerCase();
const inline=t=>esc(t).replace(/`([^`]+)`/g,'<code>$1</code>');
const KEY='ros2-lab-humble-v1';
let state={done:[],notes:{},answers:{},last:1},storageOK=true;
try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s&&typeof s==='object'){state.done=Array.isArray(s.done)?s.done.filter(n=>Number.isInteger(n)&&n>0&&n<=32):[];for(const key of ['notes','answers'])if(s[key]&&typeof s[key]==='object'&&!Array.isArray(s[key]))state[key]=s[key];if(Number.isInteger(s.last)&&s.last>0&&s.last<=32)state.last=s.last;}}catch{storageOK=false;}
let homeQuery='',homeFilter='all',dictQuery='',dictFilter='all',toastTimer;
const icons={map:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',book:'<path d="M4 4h6a3 3 0 012 2 3 3 0 013-2h5v16h-6a2 2 0 00-2 1 2 2 0 00-2-1H4zM12 6v15"/>',terminal:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="m7 9 3 3-3 3m6 0h4"/>',robot:'<rect x="5" y="7" width="14" height="13" rx="3"/><path d="M12 3v4M2 12h3m14 0h3M8 15h8"/><circle cx="9" cy="11" r=".5"/><circle cx="15" cy="11" r=".5"/>',note:'<path d="M5 3h10l4 4v14H5zM14 3v5h5M8 12h8m-8 4h6"/>',link:'<path d="m9 15 6-6m-7 2-2 2a4 4 0 006 6l2-2m2-4 2-2a4 4 0 00-6-6L10 6"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.book}</svg>`;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{if(storageOK)toast('Không lưu được tiến độ. Hãy xuất bản sao.');storageOK=false;}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800);}
const codeBlock=(code,lang='bash')=>`<div class="code-block"><div class="code-bar"><span>${esc(lang.toUpperCase())}${lang==='bash'?' · UBUNTU 22.04':''}</span><button class="copy-button" data-action="copy">Sao chép</button></div><pre><code>${esc(code)}</code></pre></div>`;
const status=id=>`<span class="status-circle ${state.done.includes(id)?'done':''}" aria-label="${state.done.includes(id)?'Đã học':'Chưa đánh dấu'}">${state.done.includes(id)?'✓':''}</span>`;
function section(s,i){return `<section id="section-${i}"><h2>${esc(s.heading)}</h2>${s.text.split('\n\n').map(p=>`<p>${inline(p)}</p>`).join('')}${s.code?codeBlock(s.code,s.lang):''}${s.table?`<div class="table-wrap"><table><thead><tr>${s.table.headers.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${s.table.rows.map(row=>`<tr>${row.map(x=>`<td>${inline(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}</section>`;}
function sidebar(route){const active=['lesson','module'].includes(route)?'home':route;$('#sidebar').innerHTML=`<a class="brand" href="#home" aria-label="ROS 2 Lab — Trang chủ"><div class="brand-mark">R_</div><div>ROS 2 Lab<small>HỌC ĐỂ TẠO NÊN</small></div></a><div class="sidebar-label">BÀN HỌC CỦA BẠN</div><nav class="side-nav">${[['home','map','Lộ trình học','32'],['project','robot','Dự án của bạn','↗'],['dictionary','book','Sổ tay câu lệnh',''],['lab','terminal','Terminal thực hành',''],['notes','note','Ghi chép của tôi','']].map(([r,ic,label,count])=>`<a class="nav-link ${active===r?'active':''}" href="#${r}" ${active===r?'aria-current="page"':''}>${icon(ic)}${label}${count?`<span class="count">${count}</span>`:''}</a>`).join('')}</nav><div class="sidebar-label">8 CHẶNG · TỪ CƠ BẢN ĐẾN NÂNG CAO</div><nav>${MODULES.map(m=>`<a class="side-module" href="#module/${m.id}"><b>${String(m.id).padStart(2,'0')}</b><span>${esc(m.title)}</span></a>`).join('')}</nav><div class="side-bottom"><div class="side-progress"><div class="row"><span>Hành trình của bạn</span><b>${Math.round(state.done.length/32*100)}%</b></div><div class="progress-track"><div style="width:${state.done.length/32*100}%"></div></div><small>${state.done.length}/32 bài đã đánh dấu hoàn thành</small></div><a class="nav-link" href="#sources">${icon('link')}Tài liệu & nguồn tham khảo</a></div>`;}
function robotArt(){return `<svg class="hero-art" viewBox="0 0 340 245" fill="none" aria-label="Minh họa ba robot kết nối thành đội hình" role="img"><defs><pattern id="grid" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M24 0H0V24" stroke="#54816a" stroke-opacity=".18"/></pattern><g id="smallbot"><path d="m15 13 27-12 27 12v36L42 63 15 49V13Z" fill="#7f9f83"/><path d="m15 13 27 14 27-14" fill="#adc7a1"/><rect x="27" y="13" width="34" height="23" rx="7" fill="#c2d8ac"/><rect x="34" y="19" width="20" height="10" rx="3" fill="#244a39"/><circle cx="39" cy="24" r="1.5" fill="#d7e9b3"/><circle cx="49" cy="24" r="1.5" fill="#d7e9b3"/><ellipse cx="17" cy="49" rx="5" ry="8" fill="#17382e"/><ellipse cx="67" cy="49" rx="5" ry="8" fill="#17382e"/></g></defs><rect width="340" height="245" fill="url(#grid)"/><ellipse cx="185" cy="205" rx="132" ry="23" fill="#102f28" opacity=".5"/><path d="m72 170 112-110 103 110H72Z" stroke="#91b277" stroke-dasharray="4 6" opacity=".6"/><g transform="translate(139 34)"><path d="M18 33 45 17 73 33v56L45 106 18 89V33Z" fill="#98b88e"/><path d="m18 33 27 17 28-17" fill="#c1d9ad"/><path d="M45 50v56" stroke="#547959"/><rect x="31" y="33" width="46" height="37" rx="10" fill="#d9e9ba" transform="rotate(-8 31 33)"/><rect x="40" y="40" width="29" height="18" rx="5" fill="#254c3a" transform="rotate(-8 40 40)"/><circle cx="48" cy="48" r="2" fill="#d9ecaf"/><circle cx="61" cy="46" r="2" fill="#d9ecaf"/><path d="M54 29V16" stroke="#b5d09c" stroke-width="3"/><circle cx="54" cy="12" r="4" fill="#e9bd76"/><ellipse cx="20" cy="89" rx="6" ry="11" fill="#17382e"/><ellipse cx="71" cy="89" rx="6" ry="11" fill="#17382e"/></g><use href="#smallbot" x="36" y="135"/><use href="#smallbot" x="237" y="135"/><rect x="12" y="51" width="100" height="41" rx="6" fill="#254c3c" stroke="#42664d"/><text x="23" y="69" font-size="8" fill="#97bb8c" font-family="monospace">$ ros2 node list</text><text x="23" y="82" font-size="7" fill="#d1e7b1" font-family="monospace">/three_robot_dstar_mpc</text><text x="142" y="230" font-size="7" fill="#9eb996" font-family="monospace" letter-spacing="2">THREE ROBOT RESCUE</text><circle cx="295" cy="61" r="15" stroke="#67855e"/><path d="m289 61 4 4 8-9" stroke="#d7e9ad" stroke-width="1.5"/></svg>`;}
function home(){const next=LESSONS.find(l=>!state.done.includes(l.id))||LESSONS[31];$('#page-title').textContent='Lộ trình của bạn';$('#main').innerHTML=`<div class="page-heading"><div><h2>Mỗi ngày, tiến thêm một bước.</h2><p>Một hành trình học ROS 2, gắn với dự án của chính bạn.</p></div><span class="chip"><span class="dot"></span> PHIÊN BẢN HUMBLE</span></div><section class="hero"><div><div class="eyebrow"><span class="dot"></span> GIÁO TRÌNH TIẾNG VIỆT · BẮT ĐẦU TỪ SỐ 0</div><h1>Từ dòng lệnh đầu tiên,<br>đến <em>robot của riêng bạn.</em></h1><p>Hiểu từng lệnh. Viết từng node. Từng bước khám phá hệ thống ba robot cứu hộ — từ <code>cd</code>, <code>ls</code> đến D* Lite và MPC.</p><a class="btn" href="#lesson/${next.id}">${state.done.length?'Tiếp tục hành trình':'Bắt đầu từ bài 01'} <span>↗</span></a><div class="hero-meta"><span>UBUNTU 22.04</span><span>PYTHON + C++</span><span>GAZEBO FORTRESS</span></div></div>${robotArt()}</section><div class="stats">${[['▤','32 bài','Có bài tập & đáp án gợi ý'],['⌘','8 chặng','Từ nhập môn đến nâng cao'],['◷','~70 giờ','Gợi ý học trong 16 tuần'],['△','3 robot','Học trên dự án của bạn']].map(([ic,a,b])=>`<div class="stat"><span class="stat-icon">${ic}</span><div><strong>${a}</strong><small>${b}</small></div></div>`).join('')}</div><div class="home-grid"><div><div class="section-heading"><div><h2>Lộ trình học tập</h2><p>Đi tuần tự nếu mới bắt đầu. Bạn cũng có thể mở bất kỳ bài nào.</p></div><a class="tiny-link" href="giao-trinh-ros2-humble.md" download>Tải giáo trình ↓</a></div><div class="search"><input id="course-search" type="search" placeholder="Tìm bài học: cd, topic, MPC, ba robot…" aria-label="Tìm bài học" value="${esc(homeQuery)}"></div><div class="filter-row" id="course-filters">${[['all','Tất cả'],['beginner','Bắt đầu'],['middle','Trung cấp'],['advanced','Nâng cao'],['remaining','Chưa hoàn thành']].map(([key,label])=>`<button class="filter ${homeFilter===key?'active':''}" data-action="course-filter" data-filter="${key}">${label}</button>`).join('')}<span class="result-count" id="result-count"></span></div><div id="course-list" class="module-list"></div></div><aside class="home-aside"><div class="panel tinted"><div class="eyebrow">HỌC CÙNG DỰ ÁN THẬT</div><h3>three-robot-rescue</h3><p>Hai package. Ba robot omni. Một lộ trình để hiểu hệ thống bạn đang xây dựng.</p><ul><li><b>01</b>Khám phá source & ROS graph</li><li><b>02</b>Theo luồng D* Lite → MPC</li><li><b>03</b>Đọc dữ liệu & đánh giá có bằng chứng</li></ul><a class="tiny-link" href="#project">Mở bản đồ dự án ↗</a></div><div class="panel"><div class="eyebrow">CÁCH HỌC GỢI Ý</div><h3>Đọc → Làm → Tự kiểm tra</h3><p>Mỗi buổi 45–90 phút. Đọc lý thuyết, tự gõ lệnh, làm bài tập rồi trả lời câu hỏi. Lưu điều bạn vừa hiểu trong phần Ghi chép.</p><ul><li><b>↳</b>~70 giờ gồm thực hành cơ bản; cài đặt, lỗi môi trường và mở rộng có thể lâu hơn.</li><li><b>↳</b>Tiến độ lưu trong trình duyệt này. Nên xuất bản sao ở mục Ghi chép.</li></ul></div><div class="panel"><div class="eyebrow">CHƯA CÀI ROS 2?</div><h3>Thử những lệnh đầu tiên</h3><p>Terminal mô phỏng giúp luyện đường dẫn và quan sát dữ liệu mẫu.</p><a class="btn secondary small" href="#lab" style="margin-top:15px">Mở terminal →</a></div></aside></div>`;filterCourses();}
function filterCourses(){const q=norm(homeQuery);let count=0;$('#course-list').innerHTML=MODULES.map(m=>{if(!(homeFilter==='all'||homeFilter==='remaining'||homeFilter==='beginner'&&m.id<=3||homeFilter==='middle'&&m.id>=4&&m.id<=6||homeFilter==='advanced'&&m.id>=7))return '';const ls=LESSONS.filter(l=>l.module===m.id&&(homeFilter!=='remaining'||!state.done.includes(l.id))&&norm([l.title,l.summary,l.project,...l.sections.map(s=>s.heading+' '+s.text)].join(' ')).includes(q));if(!ls.length)return '';count+=ls.length;return `<section class="module-card" id="module-${m.id}"><div class="module-top"><div class="module-number">${String(m.id).padStart(2,'0')}</div><div class="module-info"><div class="eyebrow">CHẶNG ${m.id} · ${esc(m.level)}</div><h3>${esc(m.title)}</h3><p>${esc(m.desc)}</p></div><div class="module-time">${esc(m.weeks)}</div></div>${ls.map(l=>`<a class="lesson-row" href="#lesson/${l.id}"><span class="lesson-index">${String(l.id).padStart(2,'0')}</span><span class="title">${esc(l.title)}</span><span class="minutes">${l.minutes}′</span>${status(l.id)}</a>`).join('')}</section>`;}).join('')||'<div class="empty">Không tìm thấy bài phù hợp. Hãy thử từ khóa khác.</div>';$('#result-count').textContent=`${count} BÀI HỌC`;}
function lesson(id,tab='theory'){const l=LESSONS.find(x=>x.id===id);if(!l){notFound();return;}if(!['theory','practice','quiz','notes'].includes(tab))tab='theory';state.last=id;save();const m=MODULES[l.module-1],done=state.done.includes(id);$('#page-title').textContent=`Bài ${String(id).padStart(2,'0')} · ${m.level}`;$('#main').innerHTML=`<div class="lesson-header"><a href="#module/${m.id}" class="tiny-link">← Chặng ${m.id}: ${esc(m.title)}</a><h1>${esc(l.title)}</h1><p>${esc(l.summary)}</p><div class="lesson-badges"><span class="chip">BÀI ${String(id).padStart(2,'0')} / 32</span><span class="chip">${l.minutes} PHÚT · ĐỌC + THỰC HÀNH</span><span class="chip">${esc(m.level.toUpperCase())}</span>${done?'<span class="chip">✓ ĐÃ ĐÁNH DẤU HỌC XONG</span>':''}</div></div><div class="lesson-layout"><div><nav class="lesson-tabs" aria-label="Nội dung bài học">${[['theory','Bài học'],['practice','Thực hành'],['quiz','Tự kiểm tra'],['notes','Ghi chép']].map(([key,label])=>`<a class="lesson-tab ${tab===key?'active':''}" href="#lesson/${id}/${key}" ${tab===key?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="article" id="lesson-content">${tab==='theory'?theory(l):tab==='practice'?practice(l):tab==='quiz'?quiz(l):lessonNotes(l)}</div><div class="lesson-bottom"><a class="btn secondary small" href="${id>1?'#lesson/'+(id-1):'#home'}">← ${id>1?'Bài trước':'Lộ trình'}</a><button class="btn small" data-action="complete" data-id="${id}">${done?'✓ Đã học xong · Bỏ đánh dấu':'Đánh dấu đã học xong'}</button><a class="btn secondary small" href="${id<32?'#lesson/'+(id+1):'#home'}">${id<32?'Bài tiếp theo':'Về lộ trình'} →</a></div></div><aside class="lesson-toc"><div class="panel"><div class="eyebrow">SAU BÀI NÀY, BẠN CÓ THỂ</div><ul class="objective-list">${l.objectives.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="panel tinted"><div class="eyebrow">GẮN VỚI DỰ ÁN CỦA BẠN</div><p>${inline(l.project)}</p><a class="tiny-link" href="#project">Bản đồ dự án ↗</a></div>${tab==='theory'?`<div class="panel"><div class="eyebrow">TRONG BÀI NÀY</div>${l.sections.map((s,i)=>`<button class="toc-link" data-action="scroll-section" data-section="${i}">${esc(s.heading)}</button>`).join('')}</div>`:''}</aside></div>`;}
function theory(l){return `${l.id>8?'<div class="callout"><strong>Chuẩn bị</strong>Lệnh ROS thực chạy trong Ubuntu đã source Humble; các terminal cùng phiên dùng ROS_DOMAIN_ID=31. Code mới dùng workspace học tập ~/ros2_learning/ws.</div>':''}${l.sections.map(section).join('')}<div class="callout"><strong>Áp dụng vào three-robot-rescue</strong>${inline(l.project)}</div><div class="source-links">Đọc thêm: <a href="${esc(l.source)}" target="_blank" rel="noopener noreferrer">Tài liệu / mã nguồn tham khảo ↗</a> · <a href="#lesson/${l.id}/practice">Làm bài thực hành →</a></div>`;}
function practice(l){return `<section><div class="eyebrow">TỰ LÀM TRƯỚC KHI XEM GỢI Ý</div><h2>Bài thực hành ${String(l.id).padStart(2,'0')}</h2><p>Tự gõ và ghi lại điều quan sát được. Tác vụ ROS/Gazebo cần môi trường thật; terminal trên website chỉ hỗ trợ một tập lệnh mẫu.</p><ol>${l.practice.steps.map(s=>`<li>${inline(s)}</li>`).join('')}</ol></section><div class="callout"><strong>Kết quả cần đạt</strong>${inline(l.practice.expected)}</div><details class="solution"><summary>Xem gợi ý & cách tự đối chiếu</summary><p style="margin-top:15px">${inline(l.practice.solution)}</p></details><div class="callout"><strong>Gắn với dự án</strong>${inline(l.project)}</div><a class="btn secondary small" href="#lesson/${l.id}/quiz">Tự kiểm tra kiến thức →</a> ${l.id<=3?'<a class="btn small" href="#lab">Mở terminal mô phỏng</a>':''}`;}
function quiz(l){const answers=state.answers[l.id]||{},correct=l.quiz.filter((q,i)=>answers[i]===q.answer).length,answered=l.quiz.filter((q,i)=>Number.isInteger(answers[i])&&answers[i]>=0&&answers[i]<q.options.length).length;return `<div class="section-heading"><div><h2>Hiểu rồi thì thử nhé.</h2><p>Chọn đáp án để xem giải thích. Đây là tự kiểm tra, không phải chứng chỉ.</p></div><span class="chip">${correct}/${l.quiz.length} ĐÚNG</span></div>${l.quiz.map((q,i)=>{const a=answers[i],has=Number.isInteger(a)&&a>=0&&a<q.options.length;return `<section class="quiz-card"><div class="eyebrow">CÂU ${i+1} / ${l.quiz.length}</div><h3>${inline(q.question)}</h3>${q.options.map((opt,j)=>`<button class="quiz-option ${has?(j===q.answer?'correct':j===a?'wrong':''):''}" data-action="answer" data-id="${l.id}" data-question="${i}" data-choice="${j}" ${has?'disabled':''}><b>${String.fromCharCode(65+j)}</b><span>${esc(opt)}</span>${has&&j===q.answer?' ✓':''}</button>`).join('')}${has?`<div class="quiz-feedback ${a!==q.answer?'wrong':''}"><b>${a===q.answer?'✓ Chính xác.':'Chưa đúng.'}</b> ${esc(q.explanation)}</div>`:''}</section>`;}).join('')}${answered===l.quiz.length?`<div class="completion-banner">Đúng ${correct}/${l.quiz.length} câu. ${correct===l.quiz.length?'Đối chiếu thêm bài thực hành rồi đánh dấu học xong.':'Đọc lại giải thích và thử lại khi sẵn sàng.'}</div>`:''}<button class="btn secondary small" data-action="reset-quiz" data-id="${l.id}">Làm lại câu hỏi</button>`;}
function lessonNotes(l){return `<section><h2>Điều bạn vừa hiểu</h2><p>Ghi lại lệnh, lỗi gặp phải và cách tự giải thích. Ghi chú chỉ lưu trong trình duyệt hiện tại, không đồng bộ máy khác.</p></section><label for="lesson-note" class="eyebrow">GHI CHÚ CÁ NHÂN · BÀI ${l.id}</label><textarea class="notes-area" id="lesson-note" data-id="${l.id}" placeholder="Ví dụ: cd .. đưa mình lên thư mục cha…">${esc(typeof state.notes[l.id]==='string'?state.notes[l.id]:'')}</textarea><p class="save-label" id="note-status">${storageOK?'Tự động lưu khi nhập.':'Bộ nhớ trình duyệt không khả dụng. Hãy xuất bản sao trước khi đóng.'}</p><a class="tiny-link" href="#notes">Xem tất cả ghi chép & xuất bản sao →</a>`;}
function dictionary(){$('#page-title').textContent='Sổ tay câu lệnh';$('#main').innerHTML=`<div class="page-heading"><div><div class="eyebrow">TRA NHANH · HIỂU ĐÚNG</div><h1>Sổ tay câu lệnh</h1><p>Lệnh hệ điều hành, công cụ ROS 2 và lệnh riêng của dự án.</p></div><a class="btn secondary small" href="#lab">Thử lệnh →</a></div><div class="callout"><strong>Linux ≠ ROS 2</strong>cd, ls và pwd là lệnh hệ điều hành. Lệnh bắt đầu bằng ros2 làm việc với ROS. Ví dụ Bash dùng Ubuntu22.04/Humble; không sao chép vào PowerShell.</div><div class="search"><input type="search" id="dict-search" aria-label="Tìm câu lệnh" placeholder="Tìm lệnh hoặc ý nghĩa…" value="${esc(dictQuery)}"></div><div class="filter-row">${['all','Linux','Shell','ROS 2','Build','Dữ liệu','Robot','Dự án'].map(f=>`<button class="filter ${dictFilter===f?'active':''}" data-action="dict-filter" data-filter="${esc(f)}">${f==='all'?'Tất cả':esc(f)}</button>`).join('')}</div><div class="dictionary-grid" id="dict-list"></div>`;filterDictionary();}
