function labPage(){$('#page-title').textContent='Terminal thực hành';$('#main').innerHTML=`<div class="page-heading"><div><div class="eyebrow">TỰ GÕ · TỰ KHÁM PHÁ</div><h1>Terminal thực hành</h1><p>Một môi trường nhỏ để câu lệnh trở nên quen thuộc.</p></div><span class="chip">MÔ PHỎNG · KHÔNG KẾT NỐI ROS</span></div><div class="callout"><strong>Dữ liệu học tập, không phải trạng thái robot thật</strong>Chỉ hỗ trợ một tập lệnh hữu hạn và cây thư mục rút gọn. Không chạy chương trình, cài phần mềm hoặc thay đổi máy tính. Mọi kết quả ros2 đều là mẫu. Gõ help để xem lệnh được hỗ trợ.</div><div class="terminal-layout"><div><div class="terminal"><div class="terminal-title"><i></i><i></i><i></i><span>duc@ros2-lab · BASH MÔ PHỎNG</span></div><div id="terminal-output" class="terminal-output" role="log" aria-live="polite" aria-label="Kết quả terminal mô phỏng"></div><form id="terminal-form" class="terminal-input"><span aria-hidden="true">$</span><input id="terminal-command" autocomplete="off" autocapitalize="off" spellcheck="false" aria-label="Nhập lệnh mô phỏng" placeholder="Gõ help rồi Enter…"><button class="copy-button" type="submit">Chạy ↵</button></form></div><div class="lab-buttons">${[['pwd','pwd'],['ls','ls'],['cd ~/three-robot-rescue','cd dự án']].map(([c,label])=>`<button class="btn secondary small" data-action="lab-command" data-command="${c}">${label}</button>`).join('')}<button class="btn secondary small" data-action="reset-lab">Đặt lại phiên</button></div></div><aside><div class="panel"><div class="eyebrow">BÀI TẬP NHỎ ĐẦU TIÊN</div><h3>Khám phá dự án trong 7 bước</h3><div id="lab-challenges"></div></div><div class="panel tinted"><h3>Hiểu trước khi sao chép</h3><p>pwd in vị trí. ls xem nội dung. cd đổi thư mục. Lệnh thành công có thể không in gì.</p><a class="tiny-link" href="#lesson/1">Quay lại bài01 →</a></div></aside></div>`;if(!lab.output.length)lab.output.push({text:'ROS2 Lab — Bash mô phỏng\nGõ help để xem lệnh. Source được rút gọn và ROS graph chỉ là mẫu.\nBạn đang ở /home/duc. Bắt đầu với pwd và ls.'});drawTerminal();drawChallenges();}
function drawTerminal(){const el=$('#terminal-output');if(!el)return;el.innerHTML=lab.output.map(o=>`<div class="${o.kind==='input'?'input-line':o.kind==='error'?'error':''}">${esc(o.text)}</div>`).join('');el.scrollTop=el.scrollHeight;}
