function terminalExecute(raw){const command=raw.trim();if(!command)return;lab.history.push(command);lab.cursor=lab.history.length;lab.output.push({kind:'input',text:`duc@lab:${lab.cwd.replace('/home/duc','~')}$ ${command}`});let result='',error=false;const tokens=command.match(/"[^"\n]*"|'[^'\n]*'|[^\s]+/g)?.map(t=>t.replace(/^(['"])(.*)\1$/,'$2'))||[],op=tokens[0],args=tokens.slice(1),arg=args[0];
 if(/[;&|><`]/.test(command)&&op!=='echo'){result='Chưa hỗ trợ pipe, redirect hoặc ghép lệnh trong mô phỏng. Nhập từng lệnh riêng; xem help.';error=true;}
 else if(op==='help')result='LỆNH MÔ PHỎNG\npwd | ls [-l, -a, -la] [path] | cd [path] | cat README.md\nmkdir [-p] path | touch file | echo text | echo $ROS_DISTRO\nsource /opt/ros/humble/setup.bash | export ROS_DOMAIN_ID=31\nros2 node list | ros2 node info /three_robot_dstar_mpc\nros2 topic list [-t] | ros2 topic info /robot1/cmd_vel [-v]\nros2 interface show geometry_msgs/msg/Twist\nclear | help\nMũi tên ↑/↓: lịch sử. Không có ROS thật hoặc tiến trình nền.';
 else if(op==='clear'){lab.output=[];drawTerminal();return;}
 else if(op==='pwd'&&args.length===0){result=lab.cwd;lab.checks.add('pwd');}
 else if(op==='cd'){if(args.length>1){result='cd: quá nhiều đối số';error=true;}else{const dest=arg==='-'?lab.previous:pathResolve(arg);if(Object.hasOwn(VFS,dest)){lab.previous=lab.cwd;lab.cwd=dest;if(arg==='-')result=dest;if(dest==='/home/duc/three-robot-rescue')lab.checks.add('cd');}else{result=`cd: không có thư mục: ${arg}`;error=true;}}}
 else if(op==='ls'){const flags=args.filter(a=>a.startsWith('-')),paths=args.filter(a=>!a.startsWith('-'));if(flags.some(f=>!/^-[la]+$/.test(f))||paths.length>1){result='ls mô phỏng hỗ trợ -l, -a, -la và một đường dẫn.';error=true;}else{const dest=pathResolve(paths[0]||'.');if(Object.hasOwn(VFS,dest)){const all=flags.some(f=>f.includes('a')),long=flags.some(f=>f.includes('l'));const entries=all?['.','..',...VFS[dest]]:VFS[dest];result=long?'[METADATA MẪU]\n'+entries.map(name=>{const p=pathResolve(dest+'/'+name);return (Object.hasOwn(VFS,p)?'drwxr-xr-x':'-rw-r--r--')+'  duc duc  '+name;}).join('\n'):entries.join('  ')||'(thư mục rỗng)';if(dest==='/home/duc/three-robot-rescue')lab.checks.add('ls');}else{result='ls: không có thư mục đó trong cây mô phỏng';error=true;}}}
 else if(op==='echo')result=args.join(' ').replace(/\$ROS_DOMAIN_ID/g,lab.domain).replace(/\$ROS_DISTRO/g,lab.sourced?'humble':'').replace(/\$PWD/g,lab.cwd);
 else if(op==='source'){if(arg==='/opt/ros/humble/setup.bash'&&args.length===1){lab.sourced=true;lab.checks.add('source');result='[MÔ PHỎNG] Đã nạp môi trường Humble.';}else{result='Chỉ hỗ trợ source /opt/ros/humble/setup.bash trong mô phỏng.';error=true;}}
 else if(op==='export'){if(args.length===1&&/^ROS_DOMAIN_ID=\d+$/.test(arg)){lab.domain=arg.split('=')[1];if(lab.domain==='31')lab.checks.add('domain');}else{result='Thử: export ROS_DOMAIN_ID=31 (không có khoảng trắng quanh =)';error=true;}}
 else if(op==='cat'){const p=pathResolve(arg||'');if(args.length!==1){result='Cú pháp: cat đường_dẫn_tệp';error=true;}else if(Object.hasOwn(VFSTEXT,p))result=VFSTEXT[p];else{const parent=p.slice(0,p.lastIndexOf('/'))||'/',name=p.slice(p.lastIndexOf('/')+1);if(VFS[parent]?.includes(name)&&!Object.hasOwn(VFS,p))result='[Nội dung chưa đưa vào mô phỏng. Xem nguồn thật ở trang Dự án.]';else{result='cat: không có tệp đó';error=true;}}}
 else if(op==='mkdir'||op==='touch'){const recursive=op==='mkdir'&&arg==='-p',target=recursive?args[1]:arg;if(!target||args.length!==(recursive?2:1)||target.startsWith('-')){result=`Cú pháp: ${op} ${op==='mkdir'?'[-p] ':''}đường_dẫn`;error=true;}else{const p=pathResolve(target),parent=p.slice(0,p.lastIndexOf('/'))||'/',name=p.slice(p.lastIndexOf('/')+1);if(!p.startsWith('/home/duc/ros2_learning/')){result='Chỉ tạo tệp/thư mục trong ~/ros2_learning/ ở mô phỏng.';error=true;}else if(Object.hasOwn(VFS,p)||VFS[parent]?.includes(name)){result=op==='mkdir'&&!recursive?'mkdir: mục đã tồn tại':'';error=Boolean(result);}else if(recursive){let curr='/home/duc/ros2_learning';for(const part of p.slice(curr.length+1).split('/')){if(VFS[curr].includes(part)&&!Object.hasOwn(VFS,curr+'/'+part)){result='mkdir: một thành phần đường dẫn là tệp';error=true;break;}if(!VFS[curr].includes(part))VFS[curr].push(part);curr+='/'+part;if(!Object.hasOwn(VFS,curr))VFS[curr]=[];}}else if(!Object.hasOwn(VFS,parent)){result='Thư mục cha chưa tồn tại; dùng mkdir -p.';error=true;}else{VFS[parent].push(name);if(op==='mkdir')VFS[p]=[];else VFSTEXT[p]='';}}}
 else if(op==='ros2'){if(!lab.sourced){result='ros2: command not found [MÔ PHỎNG]\nHãy source /opt/ros/humble/setup.bash trước.';error=true;}else if(command==='ros2 node list'){lab.checks.add('graph');result='[GRAPH MẪU, KHÔNG PHẢI RUNTIME]\n/three_robot_dstar_mpc\n/robot1_distributed_mpc\n/robot2_distributed_mpc\n/robot3_distributed_mpc\n/map_server';}else if(command==='ros2 topic list'||command==='ros2 topic list -t'){lab.checks.add('topic');result='[DỮ LIỆU MẪU]\n'+projectTopics.map(([t,type])=>t.replace('robotN','robot1')+(command.endsWith('-t')?` [${type}]`:'')).join('\n');}else if(command==='ros2 node info /three_robot_dstar_mpc')result='[TÓM TẮT MẪU]\nNode: /three_robot_dstar_mpc\nSubscriptions: /goal_pose, map (có thể remap), scan/odom ba robot\nPublishers: /dstar_lite/path, /formation/reference, /formation/robot_states\nXem CLI thật cho graph runtime.';else if(/^ros2 topic info \/robot1\/cmd_vel( -v)?$/.test(command))result='[MẪU, KHÔNG ĐO RUNTIME]\nType: geometry_msgs/msg/Twist\nVai trò: MPC phát → omni_kinematics nhận.\nSố endpoint và QoS thực tế: xem info -v trên Ubuntu.';else if(command==='ros2 interface show geometry_msgs/msg/Twist')result='[SCHEMA THAM KHẢO]\ngeometry_msgs/Vector3 linear\n  float64 x\n  float64 y\n  float64 z\ngeometry_msgs/Vector3 angular\n  float64 x\n  float64 y\n  float64 z';else{result='Lệnh ROS này chưa được mô phỏng. Xem help; chạy thực hành đầy đủ trong Ubuntu có ROS.';error=true;}}
 else{result=`Chưa hỗ trợ “${op}” trong mô phỏng. Gõ help.`;error=true;}
 if(result)lab.output.push({kind:error?'error':'output',text:result});if(lab.output.length>180)lab.output=lab.output.slice(-180);drawTerminal();drawChallenges();}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type:type+';charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportState(){download('ros2-lab-tien-do.json',JSON.stringify({format:KEY,exported:new Date().toISOString(),...state},null,2),'application/json');toast('Đã xuất tiến độ, đáp án và ghi chú.');}
async function copyFrom(button){const code=button.closest('.code-block')?.querySelector('pre code')?.textContent||'';try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(code);else{const area=document.createElement('textarea');area.value=code;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();if(!ok)throw Error('copy');}toast('Đã sao chép đoạn lệnh.');button.textContent='Đã chép ✓';setTimeout(()=>button.textContent='Sao chép',1600);}catch{toast('Hãy chọn đoạn mã và dùng Ctrl+C để sao chép.');}}
function notFound(){$('#page-title').textContent='Không tìm thấy';$('#main').innerHTML='<div class="empty"><h2>Trang này chưa có.</h2><p><a class="tiny-link" href="#home">Quay về lộ trình →</a></p></div>';}
function route(){const [page='home',param,tab]=location.hash.slice(1).split('/');sidebar(page||'home');$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');if(page==='home'||page==='')home();else if(page==='module'){homeQuery='';homeFilter='all';home();setTimeout(()=>$('#module-'+Number(param))?.scrollIntoView({block:'start'}),0);}else if(page==='lesson')lesson(Number(param),tab);else if(page==='dictionary')dictionary();else if(page==='project')project();else if(page==='notes')notes();else if(page==='lab')labPage();else if(page==='sources')sources();else notFound();document.title=(page==='lesson'?LESSONS.find(l=>l.id===Number(param))?.title||'Bài học':$('#page-title').textContent)+' — ROS 2 Lab';window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=Number(b.dataset.id);
 if(a==='skip'){e.preventDefault();$('#main').focus();}else if(a==='copy')copyFrom(b);
 else if(a==='course-filter'){homeFilter=b.dataset.filter;document.querySelectorAll('#course-filters .filter').forEach(x=>x.classList.toggle('active',x===b));filterCourses();}
 else if(a==='dict-filter'){dictFilter=b.dataset.filter;document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x===b));filterDictionary();}
 else if(a==='complete'){const y=window.scrollY;state.done=state.done.includes(id)?state.done.filter(n=>n!==id):[...state.done,id];save();route();window.scrollTo(0,y);toast(state.done.includes(id)?'Đã lưu tiến độ bài học.':'Đã bỏ đánh dấu hoàn thành.');}
 else if(a==='answer'){const qi=Number(b.dataset.question),choice=Number(b.dataset.choice),l=LESSONS.find(x=>x.id===id);if(!l?.quiz[qi]||choice<0||choice>=l.quiz[qi].options.length)return;if(!state.answers[id]||typeof state.answers[id]!=='object')state.answers[id]={};state.answers[id][qi]=choice;save();const y=window.scrollY;lesson(id,'quiz');window.scrollTo(0,y);}
 else if(a==='reset-quiz'){delete state.answers[id];save();lesson(id,'quiz');toast('Đã đặt lại câu hỏi của bài này.');}
 else if(a==='scroll-section')$('#section-'+b.dataset.section)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});
 else if(a==='export')exportState();else if(a==='import')$('#import-file').click();
 else if(a==='lab-command'){terminalExecute(b.dataset.command);$('#terminal-command').focus();}
 else if(a==='reset-lab'){for(const key of Object.keys(VFS))delete VFS[key];Object.assign(VFS,JSON.parse(INITIALVFS));for(const key of Object.keys(VFSTEXT))delete VFSTEXT[key];Object.assign(VFSTEXT,JSON.parse(INITIALTEXT));lab={cwd:'/home/duc',previous:'/home/duc',sourced:false,domain:'',history:[],cursor:0,checks:new Set(),output:[]};labPage();toast('Đã đặt lại phiên mô phỏng.');}
});
document.addEventListener('input',e=>{if(e.target.id==='course-search'){homeQuery=e.target.value;filterCourses();}else if(e.target.id==='dict-search'){dictQuery=e.target.value;filterDictionary();}else if(e.target.id==='lesson-note'){state.notes[e.target.dataset.id]=e.target.value;save();$('#note-status').textContent=storageOK?'✓ Đã lưu trên trình duyệt này.':'Chưa lưu bền vững; hãy xuất bản sao ở mục Ghi chép.';}});
document.addEventListener('submit',e=>{if(e.target.id==='terminal-form'){e.preventDefault();const input=$('#terminal-command');terminalExecute(input.value);input.value='';}});
document.addEventListener('keydown',e=>{if(e.target.id==='terminal-command'&&['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();lab.cursor=Math.max(0,Math.min(lab.history.length,lab.cursor+(e.key==='ArrowUp'?-1:1)));e.target.value=lab.history[lab.cursor]||'';}if(e.key==='Escape'){$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}});
document.addEventListener('change',async e=>{if(e.target.id!=='import-file')return;const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('file quá lớn');const data=JSON.parse(await file.text());if(data.format!==KEY||!Array.isArray(data.done)||!data.notes||typeof data.notes!=='object'||!data.answers||typeof data.answers!=='object')throw Error('sai định dạng');const validNotes={},validAnswers={};for(const l of LESSONS){if(typeof data.notes[l.id]==='string')validNotes[l.id]=data.notes[l.id].slice(0,100000);if(data.answers[l.id]&&typeof data.answers[l.id]==='object'){validAnswers[l.id]={};l.quiz.forEach((q,i)=>{const a=data.answers[l.id][i];if(Number.isInteger(a)&&a>=0&&a<q.options.length)validAnswers[l.id][i]=a;});}}state.done=[...new Set([...state.done,...data.done.filter(n=>Number.isInteger(n)&&n>0&&n<=32)])];for(const[id,note]of Object.entries(validNotes))if(note.trim())state.notes[id]=state.notes[id]&&state.notes[id]!==note?state.notes[id]+'\n\n--- Ghi chú từ bản sao ---\n'+note:note;for(const[id,answers]of Object.entries(validAnswers))state.answers[id]={...(state.answers[id]||{}),...answers};save();notes();sidebar('notes');toast('Đã gộp bản sao với dữ liệu hiện tại.');}catch{toast('Cần bản sao JSON hợp lệ từ ROS 2 Lab.');}});
$('#menu-toggle').addEventListener('click',()=>{const opened=$('#sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(opened));});
$('#print-button').addEventListener('click',()=>window.print());
window.addEventListener('hashchange',route);
route();
